<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {api,type AuthorizationStatus} from './api';
defineProps<{admin:boolean}>();const emit=defineEmits<{updated:[]}>();const status=ref<AuthorizationStatus|null>(null),file=ref<File|null>(null),error=ref(''),message=ref(''),busy=ref(false);const fileInput=ref<HTMLInputElement|null>(null);let timer:ReturnType<typeof setInterval>|undefined;
const names:Record<string,string>={Unlicensed:'尚未授权',Active:'授权有效',Expired:'已到期',ClockError:'时钟异常',Invalid:'保护状态异常'};
async function load(){status.value=await api('/api/authorization/status')}
async function request(){try{const data=await api('/api/authorization/request');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='液位管理系统-安装授权请求.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=String(e)}}
async function importFile(){if(!file.value||busy.value)return;if(file.value.size>6*1024*1024){error.value='授权文件不能超过6MB';return}busy.value=true;error.value='';try{status.value=await api('/api/authorization/import','POST',{envelopeJson:await file.value.text()});file.value=null;if(fileInput.value)fileInput.value.value='';message.value='供方授权已校验并保存，按本机授权范围生效。';emit('updated')}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>{void load().catch(e=>error.value=String(e));timer=setInterval(()=>void load().catch(e=>error.value=String(e)),3000)});onUnmounted(()=>{if(timer)clearInterval(timer)});
</script>
<template><section class="panel panel-body"><h2>软件授权</h2><p v-if="status" class="notice authorization-state"><strong>{{names[status.state]}}</strong><br>{{status.message}}<br>截止时刻：{{status.expiresAtUtc?new Date(status.expiresAtUtc).toLocaleString('zh-CN',{hour12:false}):status.state==='Active'?'永久授权':'尚未设置'}}<br><span v-if="status.reminderDays">请在到期前联系供方办理延期。</span></p><p class="help">日期由供方签发，管理员导入本机授权文件。更改登录密码或恢复业务数据库不会延长授权。到期后保留实时监控、采集归档、报警确认、停止和必要核查；已开始的原任务按后台执行上下文收尾。</p><div v-if="admin" class="authorization-cards"><section class="authorization-step"><h3>1. 保存安装请求</h3><p class="help">将此文件提供给供方，用于签发与本机绑定的授权。</p><button class="button" @click="request">保存安装授权请求</button></section><form class="authorization-step" @submit.prevent="importFile"><h3>2. 导入供方授权</h3><div class="authorization-file"><input ref="fileInput" class="visually-hidden" type="file" accept=".json" aria-label="供方授权文件" @change="file=($event.target as HTMLInputElement).files?.[0]||null"><button type="button" class="button" @click="fileInput?.click()">选择授权文件</button><span :title="file?.name">{{file?.name||'尚未选择文件'}}</span></div><button class="button primary" :disabled="!file||busy">校验并导入授权</button></form></div><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p></section></template>
